const $=(selector,scope=document)=>scope.querySelector(selector)
const $$=(selector,scope=document)=>[...scope.querySelectorAll(selector)]
const months=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC']
const fullMonths=['January','February','March','April','May','June','July','August','September','October','November','December']
let pageNumber=1,zoom=100,currentPage='cover',currentMonth=0,selectedFormat='letter',selectedOrientation='portrait',exportMode='pdf',syncingLogicalPage=false
const savedJournalYear=Number(localStorage.getItem('volunelle-journal-year'));if(savedJournalYear>=1900&&savedJournalYear<=2200)$('#journalYear').value=String(savedJournalYear)
const JOURNAL_SETTINGS_KEY='volunelle-journal-settings'
function saveJournalSettings(announce=false){const settings={title:$('#journalTitle').value,type:$('#journalType').value,audience:$('#journalAudience').value,format:selectedFormat,orientation:selectedOrientation,collection:$('#designCollection').value,mood:$('.mood-swatches button.active')?.dataset.mood||'merlot'};localStorage.setItem(JOURNAL_SETTINGS_KEY,JSON.stringify(settings));if(announce)showToast('Journal saved to your atelier')}
function restoreJournalSettings(){try{const settings=JSON.parse(localStorage.getItem(JOURNAL_SETTINGS_KEY)||'{}');if(settings.title)$('#journalTitle').value=settings.title;if(settings.type)$('#journalType').value=settings.type;if(settings.audience)$('#journalAudience').value=settings.audience;if(settings.format)selectFormat(settings.format);if(settings.orientation){selectedOrientation=settings.orientation;$$('[data-orientation]').forEach(button=>button.classList.toggle('active',button.dataset.orientation===settings.orientation))}if(settings.collection)$('#designCollection').value=settings.collection;if(settings.mood)$$('[data-mood]').forEach(button=>button.classList.toggle('active',button.dataset.mood===settings.mood))}catch{}}
restoreJournalSettings()
function journalYear(){const value=Math.trunc(Number($('#journalYear').value));return value>=1900&&value<=2200?value:2027}
function daysInMonth(monthIndex,year=journalYear()){return new Date(year,monthIndex+1,0).getDate()}

const monthTabs=$('.month-tabs')
months.forEach((month,index)=>{const button=document.createElement('button');button.textContent=month;button.className=index===0?'active':'';button.addEventListener('click',()=>selectMonth(index));monthTabs.append(button)})

function selectMonth(index){currentMonth=index;$$('.month-tabs button').forEach((button,i)=>button.classList.toggle('active',i===index));if(['cover','divider'].includes(currentPage))$('#paperContent strong').textContent=fullMonths[index];renderMiniCalendar();$('#quickTypeSample').textContent=fullMonths[index];updateCaption();showLogicalPageArtwork();syncPageNumberForPreview()}
function updateCaption(){$('#currentPageLabel').textContent=`${fullMonths[currentMonth]} · ${currentPage[0].toUpperCase()+currentPage.slice(1)}`}
function showToast(message){const toast=$('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2200)}

$$('.nav-item').forEach(button=>button.addEventListener('click',()=>{const panel=button.dataset.panel;$$('.nav-item').forEach(item=>item.classList.remove('active'));button.classList.add('active');if(panel==='studio'||panel==='typography'||panel==='calendar')openDashboardTool(panel);else if(panel==='navigation'){$('#inspector').classList.remove('open');$('.page-type[data-page="divider"]').click();$('.workspace-card').scrollIntoView({behavior:'smooth',block:'start'})}else if(panel==='export'){$('#inspector').classList.remove('open');$('.export-mini').scrollIntoView({behavior:'smooth',block:'center'})}else{openInspectorPanel(panel==='pages'?'artwork':panel);const target=panel==='pages'?$('.asset-library-head'):$('#inspector');$('#inspector').scrollTop=panel==='pages'?target.offsetTop-20:0}$$('.nav-item').forEach(item=>item.classList.toggle('active',item===button));showToast(`${button.querySelector('strong').textContent} selected`)}))
$$('.page-type').forEach(button=>button.addEventListener('click',()=>{currentPage=button.dataset.page;$$('.page-type').forEach(item=>item.classList.remove('active'));button.classList.add('active');const paper=$('#paperContent'),mark=$('#coverMark'),image=$('#journalScene img'),month=fullMonths[currentMonth];paper.hidden=false;mark.hidden=false;image.style.filter='none';if(currentPage==='cover'){paper.innerHTML=`<small>MONTH OF</small><strong>${month}</strong><i></i>`}if(currentPage==='divider'){mark.hidden=true;paper.innerHTML=`<small>MONTH OF</small><strong>${month}</strong><i></i>`}if(currentPage==='calendar'){mark.hidden=true;paper.innerHTML=`<small>${month.toUpperCase()} · ${journalYear()}</small><strong style="font-family:Cormorant Garamond;font-size:30px">A beautiful month awaits.</strong><i></i>`}if(currentPage==='entry'){mark.hidden=true;paper.innerHTML='<small>TODAY, I CHOOSE</small><strong style="font-family:Cormorant Garamond;font-size:28px">To become more of myself.</strong><i></i>'}if(currentPage==='back'){paper.hidden=true;mark.style.left='39%'}else mark.style.left='38%';updateCaption();showLogicalPageArtwork()}))

function syncPageNumberForPreview(){if(syncingLogicalPage)return;const role={cover:'front-cover',divider:'divider',calendar:'calendar',entry:'entry',back:'back-cover'}[currentPage],plan=buildLogicalPagePlan(),index=plan.findIndex(item=>item.role===role&&(!monthlyRoles.has(role)||item.month===fullMonths[currentMonth]));if(index>=0){pageNumber=index+1;$('#pageNumber').textContent=pageNumber}}
function showLogicalPageNumber(number){const plan=buildLogicalPagePlan(),total=Math.max(1,plan.length);pageNumber=Math.max(1,Math.min(total,number));const item=plan[pageNumber-1];if(!item){$('#pageNumber').textContent=pageNumber;return}syncingLogicalPage=true;if(item.month)selectMonth(fullMonths.indexOf(item.month));const pageType={'front-cover':'cover',divider:'divider',calendar:'calendar',entry:'entry','back-cover':'back'}[item.role];if(pageType)$(`.page-type[data-page="${pageType}"]`).click();else previewAsset(item.asset.id);syncingLogicalPage=false;$('#pageNumber').textContent=pageNumber}
$$('.page-type').forEach(button=>button.addEventListener('click',syncPageNumberForPreview))
$$('[data-page-step]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.pageStep,total=Math.max(1,Number($('#pageTotal').textContent)||1),next=action==='first'?1:action==='last'?total:action==='prev'?pageNumber-1:pageNumber+1;showLogicalPageNumber(next)}))
$$('[data-zoom]').forEach(button=>button.addEventListener('click',()=>{zoom=Math.max(70,Math.min(130,zoom+(button.dataset.zoom==='in'?10:-10)));$('#zoomValue').textContent=`${zoom}%`;$('#journalScene img').style.transform=`scale(${zoom/100})`}))
$$('[data-toast]').forEach(button=>button.addEventListener('click',()=>showToast(button.dataset.toast)))
$('.fit-control').addEventListener('click',()=>{zoom=100;$('#zoomValue').textContent='100%';$('#journalScene img').style.transform='scale(1)';positionLogicalArtworkImage();showToast('Preview fitted to view')})
$$('[data-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.action;if(action==='save')saveJournalSettings(true);if(action==='help')showToast('Choose Edit journal to upload pages and adjust every detail');if(action==='notifications')showToast('You are all caught up');if(action==='profile')showToast('Crown&Craft Studio · VOLUNELLE founder');if(action==='home'){selectMonth(0);$('.page-type[data-page="cover"]').click();scrollTo({top:0,behavior:'smooth'})}if(action==='center-preview'){zoom=100;$('#zoomValue').textContent='100%';$('#journalScene img').style.transform='scale(1)';positionLogicalArtworkImage();$('.workspace-card').scrollIntoView({behavior:'smooth',block:'start'});showToast('Preview centered')}}))
$$('.format').forEach(button=>button.addEventListener('click',()=>{selectFormat(button.dataset.format);if(button.dataset.format==='goodnotes')setExportMode('goodnotes');saveJournalSettings()}))
$$('.segmented button').forEach(button=>button.addEventListener('click',()=>{const group=button.parentElement;$$('button',group).forEach(item=>item.classList.remove('active'));button.classList.add('active');selectedOrientation=button.dataset.orientation;saveJournalSettings()}))
$$('[data-export-mode]').forEach(button=>button.addEventListener('click',()=>setExportMode(button.dataset.exportMode)))
$$('.mood-swatches button').forEach(button=>button.addEventListener('click',()=>{$$('.mood-swatches button').forEach(item=>item.classList.remove('active'));button.classList.add('active');saveJournalSettings();showToast('Collection mood saved')}))
$('#journalTitle').addEventListener('input',event=>{$('.canvas-title')?.remove();document.title=`${event.target.value||'Untitled'} — VOLUNELLE`;renderDynamicPageLayer();saveJournalSettings()})
$('#journalType').addEventListener('change',()=>saveJournalSettings())
$('#journalAudience').addEventListener('input',()=>saveJournalSettings())
function applyJournalYear(announce=false){const input=$('#journalYear'),value=Math.trunc(Number(input.value));if(value<1900||value>2200)return;localStorage.setItem('volunelle-journal-year',String(value));renderMiniCalendar();markPdfEngineDirty();updatePreviewPageTotal();if(currentPage==='calendar')$('.page-type[data-page="calendar"]').click();if(announce)showToast(`${value} calendar applied`)}
$('#journalYear').addEventListener('input',()=>applyJournalYear(false))
$('#journalYear').addEventListener('change',()=>{const year=journalYear();$('#journalYear').value=String(year);applyJournalYear(true)})
$('#journalForm').addEventListener('submit',event=>{event.preventDefault();saveJournalSettings();openDashboardTool('studio');showToast('Your foundation is saved · Design Studio opened')})
$('#openInspector').addEventListener('click',()=>$('#inspector').classList.add('open'))
$('#closeInspector').addEventListener('click',()=>$('#inspector').classList.remove('open'))

function renderMiniCalendar(){const dates=$('#miniDates'),year=journalYear(),firstDay=new Date(year,currentMonth,1).getDay(),total=daysInMonth(currentMonth,year);dates.replaceChildren();$('#miniCalendarMonth').textContent=fullMonths[currentMonth];for(let index=0;index<42;index+=1){const span=document.createElement('span'),day=index-firstDay+1;span.textContent=day>=1&&day<=total?String(day):'';if(day===new Date().getDate()&&currentMonth===new Date().getMonth()&&year===new Date().getFullYear())span.className='today';dates.append(span)}}
$$('[data-mini-month]').forEach(button=>button.addEventListener('click',()=>{const direction=button.dataset.miniMonth==='next'?1:-1;selectMonth((currentMonth+direction+12)%12);if(currentPage!=='calendar')$('.page-type[data-page="calendar"]').click()}))
renderMiniCalendar()

const DB_NAME='volunelle-atelier',DB_VERSION=1,ASSET_STORE='journal-pages',MAX_FILE_SIZE=30*1024*1024
const allowedTypes=new Set(['image/png','image/jpeg','image/webp','application/pdf'])
const roleLabels={'front-cover':'Front cover',divider:'Month divider',calendar:'Calendar',entry:'Journal entry','back-cover':'Back cover',additional:'Additional page'}
const monthlyRoles=new Set(['divider','calendar','entry'])
let journalAssets=[],thumbnailUrls=[],activePreviewUrl='',selectedAssetId='',pendingReplacementId='',promptCreationMode='guided'
const DYNAMIC_STYLE_KEY='volunelle-dynamic-page-style'
const CALENDAR_ARTWORK_KEY='volunelle-calendar-artwork-style'
const dynamicDefaults={divider:{x:50,y:50,size:42,color:'#6b1738',font:'serif',weight:'bold',align:'center',shadow:true},calendar:{headerX:50,headerY:10,headerSize:24,color:'#4a1027',font:'serif',gridX:10,gridY:22,gridWidth:80,gridHeight:62,gridLines:true}}
function loadDynamicStyle(){try{const stored=JSON.parse(localStorage.getItem(DYNAMIC_STYLE_KEY)||'{}');return {divider:{...dynamicDefaults.divider,...stored.divider},calendar:{...dynamicDefaults.calendar,...stored.calendar}}}catch{return structuredClone(dynamicDefaults)}}
let dynamicStyle=loadDynamicStyle(),activeDynamicPanel='divider',calendarArtworkStyle={fit:'contain',inset:4,showSafe:true,...(()=>{try{return JSON.parse(localStorage.getItem(CALENDAR_ARTWORK_KEY)||'{}')}catch{return {}}})()}
function cssFontFamily(value){return value==='sans'?'Manrope, sans-serif':value==='typewriter'?'Courier New, monospace':'Cormorant Garamond, Georgia, serif'}
function updateDynamicLayerBounds(){const layer=$('#dynamicPageLayer'),scene=$('#journalScene'),sceneWidth=scene.clientWidth,sceneHeight=scene.clientHeight,[pageWidth,pageHeight]=pageSizeForSelection(),ratio=pageWidth/pageHeight;let width=sceneWidth,height=width/ratio;if(height>sceneHeight){height=sceneHeight;width=height*ratio}const left=(sceneWidth-width)/2,top=(sceneHeight-height)/2;layer.style.left=`${left}px`;layer.style.top=`${top}px`;layer.style.width=`${width}px`;layer.style.height=`${height}px`;return {width,height,left,top}}
function enableDynamicTextTouch(element,{group,xKey,yKey,sizeKey,minSize,maxSize}){element.classList.add('dynamic-text-touch');element.setAttribute('role','group');element.setAttribute('aria-label','Drag to move text. Drag the corner handle to resize.');const handle=document.createElement('span');handle.className='dynamic-text-resize';handle.setAttribute('role','button');handle.setAttribute('aria-label','Resize text');element.append(handle);element.addEventListener('pointerdown',event=>{if(event.button!==undefined&&event.button!==0)return;event.preventDefault();const resizing=event.target===handle,startX=event.clientX,startY=event.clientY,startStyle={...dynamicStyle[group]},bounds=$('#dynamicPageLayer').getBoundingClientRect();element.classList.add('editing');const move=moveEvent=>{moveEvent.preventDefault();if(resizing){const pageScale=792/Math.max(1,bounds.height),delta=(moveEvent.clientX-startX+moveEvent.clientY-startY)*.22*pageScale;dynamicStyle[group][sizeKey]=Math.round(Math.max(minSize,Math.min(maxSize,startStyle[sizeKey]+delta)));element.style.fontSize=`${Math.max(group==='divider'?10:9,dynamicStyle[group][sizeKey]*bounds.height/792)}px`}else{dynamicStyle[group][xKey]=Math.round(Math.max(5,Math.min(95,(moveEvent.clientX-bounds.left)/bounds.width*100)));dynamicStyle[group][yKey]=Math.round(Math.max(4,Math.min(95,(moveEvent.clientY-bounds.top)/bounds.height*100)));element.style.left=`${dynamicStyle[group][xKey]}%`;element.style.top=`${dynamicStyle[group][yKey]}%`}syncDynamicControls()};const finish=()=>{element.classList.remove('editing');document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',finish);document.removeEventListener('pointercancel',finish);persistDynamicStyle();showToast(resizing?'Text size saved':'Text placement saved')};document.addEventListener('pointermove',move,{passive:false});document.addEventListener('pointerup',finish);document.addEventListener('pointercancel',finish)})}
function renderDynamicPageLayer(){const layer=$('#dynamicPageLayer'),scene=$('#journalScene'),asset=logicalAssetForCurrentPage?.();layer.replaceChildren();if(!scene.classList.contains('logical-artwork')||!asset||!['cover','back','divider','calendar'].includes(currentPage)){layer.hidden=true;return}layer.hidden=false;const {width,height}=updateDynamicLayerBounds(),month=fullMonths[currentMonth],year=journalYear();if(['cover','back'].includes(currentPage)){const title=$('#journalTitle').value.trim();if(!title){layer.hidden=true;return}const label=document.createElement('div');label.className='dynamic-cover-title';label.textContent=title;label.style.top=currentPage==='back'?'82%':'50%';label.style.fontSize=`${Math.max(14,34*height/792)}px`;layer.append(label);return}if(currentPage==='divider'){const style=dynamicStyle.divider,label=document.createElement('div');label.className='dynamic-divider-label';label.textContent=month;label.style.left=`${style.x}%`;label.style.top=`${style.y}%`;label.style.fontSize=`${Math.max(10,style.size*height/792)}px`;label.style.fontFamily=cssFontFamily(style.font);label.style.fontWeight=style.weight==='bold'?'700':'400';label.style.color=style.color;label.style.transform=`translate(${style.align==='left'?'0':style.align==='right'?'-100%':'-50%'},-50%)`;label.style.textAlign=style.align;label.style.textShadow=style.shadow?'0 2px 5px rgba(30,4,14,.28)':'none';layer.append(label);enableDynamicTextTouch(label,{group:'divider',xKey:'x',yKey:'y',sizeKey:'size',minSize:18,maxSize:72});return}const style=dynamicStyle.calendar,header=document.createElement('div');header.className='dynamic-calendar-header';header.textContent=`${month} ${year}`;header.style.left=`${style.headerX}%`;header.style.top=`${style.headerY}%`;header.style.fontSize=`${Math.max(9,style.headerSize*height/792)}px`;header.style.fontFamily=cssFontFamily(style.font);header.style.fontWeight='700';header.style.color=style.color;layer.append(header);enableDynamicTextTouch(header,{group:'calendar',xKey:'headerX',yKey:'headerY',sizeKey:'headerSize',minSize:14,maxSize:48});const grid=document.createElement('div');grid.className=`dynamic-calendar-grid${style.gridLines?' with-lines':''}`;grid.style.left=`${style.gridX}%`;grid.style.top=`${style.gridY}%`;grid.style.width=`${style.gridWidth}%`;grid.style.height=`${style.gridHeight}%`;grid.style.fontFamily=cssFontFamily(style.font);grid.style.color=style.color;['SUN','MON','TUE','WED','THU','FRI','SAT'].forEach(day=>{const cell=document.createElement('div');cell.className='dynamic-calendar-cell weekday';cell.textContent=day;grid.append(cell)});const firstDay=new Date(year,currentMonth,1).getDay(),totalDays=daysInMonth(currentMonth,year);for(let index=0;index<42;index+=1){const cell=document.createElement('div'),day=index-firstDay+1;cell.className='dynamic-calendar-cell';cell.textContent=day>=1&&day<=totalDays?String(day):'';grid.append(cell)}layer.append(grid);if(calendarArtworkStyle.showSafe){const safe=document.createElement('div');safe.className='calendar-safe-frame';safe.style.inset=`${calendarArtworkStyle.inset}%`;layer.append(safe)}}
function persistDynamicStyle(){localStorage.setItem(DYNAMIC_STYLE_KEY,JSON.stringify(dynamicStyle));syncQuickTypography();renderDynamicPageLayer();markPdfEngineDirty()}
function syncDynamicControls(){const d=dynamicStyle.divider,c=dynamicStyle.calendar,mappings={dividerX:d.x,dividerY:d.y,dividerSize:d.size,dividerColor:d.color,dividerFont:d.font,dividerWeight:d.weight,dividerAlign:d.align,calendarHeaderX:c.headerX,calendarHeaderY:c.headerY,calendarHeaderSize:c.headerSize,calendarColor:c.color,calendarGridX:c.gridX,calendarGridY:c.gridY,calendarGridWidth:c.gridWidth,calendarGridHeight:c.gridHeight,calendarFont:c.font};Object.entries(mappings).forEach(([id,value])=>{$(`#${id}`).value=String(value)});$('#dividerShadow').checked=d.shadow;$('#calendarGridLines').checked=c.gridLines;[['dividerXValue',d.x,'%'],['dividerYValue',d.y,'%'],['dividerSizeValue',d.size,' pt'],['calendarHeaderXValue',c.headerX,'%'],['calendarHeaderYValue',c.headerY,'%'],['calendarHeaderSizeValue',c.headerSize,' pt'],['calendarGridXValue',c.gridX,'%'],['calendarGridYValue',c.gridY,'%'],['calendarGridWidthValue',c.gridWidth,'%'],['calendarGridHeightValue',c.gridHeight,'%']].forEach(([id,value,suffix])=>{$(`#${id}`).textContent=`${value}${suffix}`})}

const promptBlueprints={
  'front-cover':{name:'front cover',composition:'Create a polished focal composition with refined edge detailing and a generous, quiet central title area.',safeZone:'Keep the central 58% of the cover visually calm and readable for a dynamic journal title, subtitle and author name.',forbid:'Do not render a title, subtitle, author, initials, monogram, logo, letters, words or numbers.'},
  divider:{name:'monthly divider',composition:'Create a luxurious chapter-opening composition with a clearly defined blank plaque or calm focal area for the month name.',safeZone:'Reserve a clean centered plaque at approximately 35–65% of the page height for a dynamically rendered month name.',forbid:'Do not render a month, “MONTH OF”, date, season, letters, words or numbers.'},
  calendar:{name:'monthly calendar',composition:'Create an elegant decorative calendar surround with a calm header and a large unobstructed planning area.',safeZone:'Keep the upper header clear for month and year. Keep the central 78% of the page blank for VOLUNELLE’s editable calendar grid.',forbid:'Do not render a month, year, weekday, calendar grid, date number, appointment, letters, words or numbers.'},
  entry:{name:'daily journal entry',composition:'Create a refined writing-page frame with restrained decoration around the edges and ample breathing room.',safeZone:'Keep the top header clear for the dynamic day and date. Preserve at least 76% of the page as a bright, low-contrast writing area; subtle writing guides are permitted.',forbid:'Do not render a date, day, prompt, quotation, heading, letters, words or numbers.'},
  'back-cover':{name:'back cover',composition:'Create a finished coordinating back cover with balanced edge decoration and a sophisticated quiet center.',safeZone:'Keep the lower-center area calm for an optional dynamic imprint, website or closing line.',forbid:'Do not render an imprint, website, slogan, barcode, logo, letters, words or numbers.'}
}
function promptCanvasDescription(){const sizes={letter:'8.5 × 11 inch',a4:'A4 210 × 297 mm',a5:'A5 148 × 210 mm',goodnotes:'3:4 digital planner canvas, 1536 × 2048 pixels'},size=sizes[selectedFormat]||sizes.letter;return `${size}, ${selectedOrientation} orientation`}
function createArtworkPrompt(){const role=$('#promptPageType').value,blueprint=promptBlueprints[role],production=[`Canvas: ${promptCanvasDescription()}. Full-bleed, flat front-facing page artwork only.`,`MANDATORY EDITABLE SAFE ZONE: ${blueprint.safeZone}`,`MANDATORY TYPOGRAPHY RULE: ${blueprint.forbid}`,`Production requirements: high resolution, print-ready, crisp refined details, no perspective mockup, no book, no hands, no room scene, no watermark, no signature, no crop marks. The result must be a single finished ${blueprint.name} page image that can be uploaded as a reusable VOLUNELLE master template.`];if(promptCreationMode==='custom'){const custom=$('#customArtworkPrompt').value.trim();if(!custom)return '';return [custom,'— VOLUNELLE MASTER-PAGE REQUIREMENTS —',...production].join('\n\n')}const style=$('#promptStyle').value,palette=$('#promptPalette').value.trim(),notes=$('#promptNotes').value.trim();return [`Create one premium ${blueprint.name} master artwork for a luxury women’s journal.`,`Art direction: ${style}. Color story: ${palette||'deep merlot, champagne gold and warm ivory'}.`,blueprint.composition,notes?`Additional creative direction: ${notes}`:'',...production].filter(Boolean).join('\n\n')}

$$('[data-prompt-mode]').forEach(button=>button.addEventListener('click',()=>{promptCreationMode=button.dataset.promptMode;$$('[data-prompt-mode]').forEach(item=>item.classList.toggle('active',item===button));$('#guidedPromptFields').hidden=promptCreationMode!=='guided';$('#customPromptFields').hidden=promptCreationMode!=='custom';$('#promptResult').hidden=true;$('#generateArtworkPrompt').firstChild.textContent=promptCreationMode==='custom'?'Prepare custom production prompt ':'Create master-page prompt '}))
$('#generateArtworkPrompt').addEventListener('click',()=>{const prompt=createArtworkPrompt(),role=$('#promptPageType').value;if(!prompt){$('#customArtworkPrompt').focus();showToast('Write your custom design vision first');return}$('#artworkPromptOutput').value=prompt;$('#promptGuardrail').textContent=promptCreationMode==='custom'?`Your custom vision is preserved. Only ${roleLabels[role].toLowerCase()} production rules were appended.`:`Protected for ${roleLabels[role]}: changing text and dates remain separate from the artwork.`;$('#promptResult').hidden=false;showToast(promptCreationMode==='custom'?'Custom prompt prepared':'Master-page prompt composed')})
$('#copyArtworkPrompt').addEventListener('click',async()=>{const output=$('#artworkPromptOutput');let copied=false;try{await navigator.clipboard.writeText(output.value);copied=true}catch{}if(!copied){output.focus();output.select();copied=document.execCommand('copy')}showToast(copied?'Prompt copied — ready for your image creator':'Prompt selected — press Ctrl+C to copy')})
$('#preparePromptUpload').addEventListener('click',()=>{const role=$('#promptPageType').value;$('#defaultPageRole').value=role;showToast(`${roleLabels[role]} upload prepared`);$('#artworkInput').click()})

const dynamicBindings={dividerX:['divider','x','number'],dividerY:['divider','y','number'],dividerSize:['divider','size','number'],dividerColor:['divider','color','value'],dividerFont:['divider','font','value'],dividerWeight:['divider','weight','value'],dividerAlign:['divider','align','value'],dividerShadow:['divider','shadow','checked'],calendarHeaderX:['calendar','headerX','number'],calendarHeaderY:['calendar','headerY','number'],calendarHeaderSize:['calendar','headerSize','number'],calendarColor:['calendar','color','value'],calendarGridX:['calendar','gridX','number'],calendarGridY:['calendar','gridY','number'],calendarGridWidth:['calendar','gridWidth','number'],calendarGridHeight:['calendar','gridHeight','number'],calendarFont:['calendar','font','value'],calendarGridLines:['calendar','gridLines','checked']}
Object.entries(dynamicBindings).forEach(([id,[group,key,type]])=>{$(`#${id}`).addEventListener('input',event=>{dynamicStyle[group][key]=type==='number'?Number(event.target.value):type==='checked'?event.target.checked:event.target.value;syncDynamicControls();persistDynamicStyle()})})
$$('[data-dynamic-panel]').forEach(button=>button.addEventListener('click',()=>{activeDynamicPanel=button.dataset.dynamicPanel;$$('[data-dynamic-panel]').forEach(item=>item.classList.toggle('active',item===button));$('#dividerDynamicControls').hidden=activeDynamicPanel!=='divider';$('#calendarDynamicControls').hidden=activeDynamicPanel!=='calendar';$(`.page-type[data-page="${activeDynamicPanel}"]`).click()}))
$('#resetDynamicStyle').addEventListener('click',()=>{dynamicStyle[activeDynamicPanel]={...dynamicDefaults[activeDynamicPanel]};syncDynamicControls();persistDynamicStyle();showToast(`${activeDynamicPanel==='divider'?'Divider':'Calendar'} placement reset`)})
function syncCalendarArtworkControls(){$('#calendarArtworkFit').value=calendarArtworkStyle.fit;$('#calendarArtworkInset').value=String(calendarArtworkStyle.inset);$('#calendarInsetValue').textContent=`${calendarArtworkStyle.inset}%`;$('#showCalendarSafeArea').checked=calendarArtworkStyle.showSafe}
function persistCalendarArtworkStyle(){localStorage.setItem(CALENDAR_ARTWORK_KEY,JSON.stringify(calendarArtworkStyle));positionLogicalArtworkImage();renderDynamicPageLayer();markPdfEngineDirty()}
$('#calendarArtworkFit').addEventListener('change',event=>{calendarArtworkStyle.fit=event.target.value;persistCalendarArtworkStyle()})
