function openDashboardTool(tool){$$('.nav-item').forEach(item=>item.classList.toggle('active',item.dataset.panel==='artwork'));openInspectorPanel('artwork');if(tool==='calendar')$('[data-dynamic-panel="calendar"]').click();if(tool==='typography')$('[data-dynamic-panel="divider"]').click();const target=tool==='studio'?$('.prompt-atelier'):tool==='calendar'?$('.calendar-master-studio'):$('.dynamic-designer');$('#inspector').scrollTop=target.offsetTop-20;showToast(tool==='studio'?'Prompt Atelier opened':tool==='calendar'?'Calendar Master Studio opened':'Dynamic typography opened')}
function applyDesignPreset(key,open=false){const preset=designPresets[key]||designPresets.merlot;$$('[data-design-preset]').forEach(button=>button.classList.toggle('selected',button.dataset.designPreset===key));$('#activePresetName').textContent=preset.name;$('#promptStyle').value=preset.style;$('#promptPalette').value=preset.palette;$('#designCollection').value=preset.name;$$('.palette-row i').forEach((swatch,index)=>swatch.style.setProperty('--swatch',preset.swatches[index]));localStorage.setItem('volunelle-design-preset',key);saveJournalSettings();if(open){$('[data-prompt-mode="guided"]').click();openDashboardTool('studio');showToast(`${preset.name} prompt preset ready`)}}
