function openInspectorPanel(panel){
  const artworkOpen=panel==='artwork'
  $('#journalForm').hidden=artworkOpen;$('#artworkPanel').hidden=!artworkOpen
  $('.inspector-head p').textContent=artworkOpen?'Artwork library':'Journal essentials'
  $('.inspector-head h2').textContent=artworkOpen?'Dress every page.':'Begin with intention.'
  $('.progress span').style.width=artworkOpen?'50%':'16%'
  if(innerWidth<=1200)$('#inspector').classList.add('open')
}

function openArtworkDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(ASSET_STORE))request.result.createObjectStore(ASSET_STORE,{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function withAssetStore(mode,work){const db=await openArtworkDatabase();return new Promise((resolve,reject)=>{const transaction=db.transaction(ASSET_STORE,mode),store=transaction.objectStore(ASSET_STORE),result=work(store);transaction.oncomplete=()=>{db.close();resolve(result?.result)};transaction.onerror=()=>{db.close();reject(transaction.error)};transaction.onabort=()=>{db.close();reject(transaction.error)}})}
function updatePreviewPageTotal(){const total=Math.max(1,buildLogicalPagePlan().length);$('#pageTotal').textContent=String(total);pageNumber=Math.min(pageNumber,total);$('#pageNumber').textContent=String(pageNumber)}
function markPdfEngineDirty(){const status=$('#pdfEngineStatus');if(status)status.textContent=journalAssets.length?`PDF engine · ${buildLogicalPagePlan().length} pages ready`:'PDF engine · awaiting monthly pages';window.volunelleLastExportAudit=null}
async function loadJournalAssets(){const records=await withAssetStore('readonly',store=>store.getAll());journalAssets=(records||[]).map(asset=>({...asset,month:monthlyRoles.has(asset.role)?asset.month||'all':''})).sort((a,b)=>a.order-b.order);renderAssetLibrary();markPdfEngineDirty();updatePreviewPageTotal();showLogicalPageArtwork()}
async function saveAsset(asset){await withAssetStore('readwrite',store=>store.put(asset))}
async function deleteAsset(id){await withAssetStore('readwrite',store=>store.delete(id))}

function validFile(file){const extension=file.name.split('.').pop()?.toLowerCase(),validExtension=['png','jpg','jpeg','webp','pdf'].includes(extension);return (allowedTypes.has(file.type)||validExtension)&&file.size<=MAX_FILE_SIZE}
function normalizedType(file){if(file.type)return file.type;return file.name.toLowerCase().endsWith('.pdf')?'application/pdf':file.name.toLowerCase().endsWith('.webp')?'image/webp':file.name.toLowerCase().endsWith('.png')?'image/png':'image/jpeg'}
async function receiveFiles(fileList){
  const files=[...fileList]
  if(!files.length)return
  if(pendingReplacementId){const file=files[0],existing=journalAssets.find(asset=>asset.id===pendingReplacementId);pendingReplacementId='';if(!validFile(file)){showToast('Choose a PNG, JPG, WEBP or PDF under 30 MB');return}const updated={...existing,name:file.name,type:normalizedType(file),size:file.size,blob:file,updatedAt:Date.now()};await saveAsset(updated);await loadJournalAssets();previewAsset(updated.id);showToast('Page artwork replaced');return}
  let added=0
  for(const file of files){if(!validFile(file)){showToast(`${file.name} was skipped`);continue}const role=$('#defaultPageRole').value,asset={id:crypto.randomUUID(),name:file.name,type:normalizedType(file),size:file.size,blob:file,role,month:monthlyRoles.has(role)?'all':'',order:Date.now()+added,createdAt:Date.now()};await saveAsset(asset);added+=1}
  await loadJournalAssets();if(added){previewAsset(journalAssets.at(-1).id);showToast(`${added} journal page${added===1?'':'s'} added`)}
}

function formatFileSize(bytes){return bytes<1024*1024?`${Math.max(1,Math.round(bytes/1024))} KB`:`${(bytes/1024/1024).toFixed(1)} MB`}
function releaseThumbnailUrls(){thumbnailUrls.forEach(URL.revokeObjectURL);thumbnailUrls=[]}
function renderAssetLibrary(){
  releaseThumbnailUrls();const library=$('#assetLibrary');library.replaceChildren();$('#assetCount').textContent=`${journalAssets.length} page${journalAssets.length===1?'':'s'} added`
  if(!journalAssets.length){const empty=document.createElement('div');empty.className='empty-library';empty.innerHTML='<span>❧</span><p>Your uploaded pages will appear here.</p>';library.append(empty);return}
  journalAssets.forEach((asset,index)=>{
    const item=document.createElement('article');item.className=`asset-item${asset.id===selectedAssetId?' selected':''}`;item.dataset.assetId=asset.id
    const thumb=document.createElement('div');thumb.className='asset-thumb'
    if(asset.type.startsWith('image/')){const url=URL.createObjectURL(asset.blob);thumbnailUrls.push(url);const image=document.createElement('img');image.src=url;image.alt='';thumb.append(image)}else{const badge=document.createElement('span');badge.className='pdf-badge';badge.textContent='PDF';thumb.append(badge)}
    const kind=document.createElement('small');kind.textContent=asset.type==='application/pdf'?'PDF':'IMAGE';thumb.append(kind)
    const details=document.createElement('div');details.className='asset-details';const name=document.createElement('strong');name.textContent=asset.name
    const meta=document.createElement('div');meta.className='asset-meta';meta.innerHTML=`<span>PAGE ${String(index+1).padStart(2,'0')}</span><span>${formatFileSize(asset.size)}</span>`
    const role=document.createElement('select');role.setAttribute('aria-label',`Page role for ${asset.name}`);Object.entries(roleLabels).forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;option.selected=asset.role===value;role.append(option)})
    const month=document.createElement('select');month.className='asset-month';month.setAttribute('aria-label',`Month assignment for ${asset.name}`);[['all','Master — all 12 months'],...fullMonths.map(value=>[value,value])].forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;option.selected=(asset.month||'all')===value;month.append(option)});month.hidden=!monthlyRoles.has(asset.role)
    role.addEventListener('change',async()=>{asset.role=role.value;asset.month=monthlyRoles.has(asset.role)?asset.month||'all':'';month.hidden=!monthlyRoles.has(asset.role);month.value=asset.month||'all';await saveAsset(asset);markPdfEngineDirty();updatePreviewPageTotal();showLogicalPageArtwork();showToast(`Assigned as ${roleLabels[asset.role]}`)})
    month.addEventListener('change',async()=>{asset.month=month.value;await saveAsset(asset);markPdfEngineDirty();updatePreviewPageTotal();showLogicalPageArtwork();showToast(month.value==='all'?'Master page will repeat for all 12 months':`Assigned to ${month.value}`)})
    const actions=document.createElement('div');actions.className='asset-actions'
    const preview=document.createElement('button');preview.type='button';preview.textContent='Preview';preview.addEventListener('click',()=>previewAsset(asset.id))
    const replace=document.createElement('button');replace.type='button';replace.textContent='Replace';replace.addEventListener('click',()=>{pendingReplacementId=asset.id;$('#artworkInput').click()})
    const up=document.createElement('button');up.type='button';up.textContent='↑';up.title='Move page earlier';up.disabled=index===0;up.addEventListener('click',()=>moveAsset(index,-1))
    const down=document.createElement('button');down.type='button';down.textContent='↓';down.title='Move page later';down.disabled=index===journalAssets.length-1;down.addEventListener('click',()=>moveAsset(index,1))
    const remove=document.createElement('button');remove.type='button';remove.className='remove-asset';remove.textContent='×';remove.title='Remove page';remove.addEventListener('click',()=>removeArtwork(asset))
    actions.append(preview,replace,up,down,remove);details.append(name,meta,role,month,actions);item.append(thumb,details);item.addEventListener('dblclick',()=>previewAsset(asset.id));library.append(item)
  })
}

async function moveAsset(index,direction){const other=index+direction;if(other<0||other>=journalAssets.length)return;const first=journalAssets[index],second=journalAssets[other];[first.order,second.order]=[second.order,first.order];await Promise.all([saveAsset(first),saveAsset(second)]);await loadJournalAssets()}
async function removeArtwork(asset){if(!confirm(`Remove “${asset.name}” from this journal?`))return;await deleteAsset(asset.id);if(selectedAssetId===asset.id)restoreAtelierPreview();await loadJournalAssets();showToast('Page removed')}
function setStudioOverlays(hidden){[$('#coverMark'),$('#paperContent'),$('.scene-vignette'),$('.month-tabs')].forEach(element=>element.hidden=hidden)}
function logicalAssetForCurrentPage(){const role={cover:'front-cover',divider:'divider',calendar:'calendar',entry:'entry',back:'back-cover'}[currentPage],candidates=journalAssets.filter(asset=>asset.role===role);if(!monthlyRoles.has(role))return candidates[0];const month=fullMonths[currentMonth];return candidates.find(asset=>asset.month===month)||candidates.find(asset=>asset.month==='all')}
function resetArtworkImageLayout(image){image.style.position='';image.style.left='';image.style.top='';image.style.width='100%';image.style.height='100%';image.style.padding=''}
function positionLogicalArtworkImage(){const scene=$('#journalScene'),image=$('#journalScene>img'),asset=logicalAssetForCurrentPage();if(!scene.classList.contains('logical-artwork')||!asset||image.hidden)return;const {left,top,width,height}=updateDynamicLayerBounds(),calendar=asset.role==='calendar',inset=calendar&&calendarArtworkStyle.fit==='inset'?calendarArtworkStyle.inset:0;image.style.position='absolute';image.style.left=`${left+width*inset/100}px`;image.style.top=`${top+height*inset/100}px`;image.style.width=`${width*(1-inset*2/100)}px`;image.style.height=`${height*(1-inset*2/100)}px`;image.style.objectFit=calendar&&calendarArtworkStyle.fit==='cover'?'cover':'contain';image.style.transform='scale(1)'}
function showDefaultAtelierScene(){if(activePreviewUrl)URL.revokeObjectURL(activePreviewUrl);activePreviewUrl='';selectedAssetId='';const scene=$('#journalScene'),image=$('#journalScene>img'),pdf=$('#assetPdfPreview');scene.classList.remove('logical-artwork');pdf.hidden=true;pdf.removeAttribute('src');image.hidden=false;resetArtworkImageLayout(image);image.src='assets/atelier-journal.png';image.style.objectFit='cover';image.style.transform=`scale(${zoom/100})`;$('.scene-vignette').hidden=false;$('.month-tabs').hidden=false;$('#paperContent').hidden=currentPage==='back';$('#coverMark').hidden=['divider','calendar','entry'].includes(currentPage);$('#dynamicPageLayer').hidden=true;updateCaption()}
function showLogicalPageArtwork(){const asset=logicalAssetForCurrentPage();if(!asset){showDefaultAtelierScene();return}selectedAssetId=asset.id;if(activePreviewUrl)URL.revokeObjectURL(activePreviewUrl);activePreviewUrl=URL.createObjectURL(asset.blob);const scene=$('#journalScene'),image=$('#journalScene>img'),pdf=$('#assetPdfPreview');scene.classList.add('logical-artwork');if(asset.type==='application/pdf'){image.hidden=true;pdf.hidden=false;pdf.src=`${activePreviewUrl}#toolbar=0&navpanes=0&view=FitH`}else{pdf.hidden=true;pdf.removeAttribute('src');image.hidden=false;image.onload=()=>{positionLogicalArtworkImage();renderDynamicPageLayer()};image.src=activePreviewUrl;positionLogicalArtworkImage()}$('#coverMark').hidden=true;$('#paperContent').hidden=true;$('.scene-vignette').hidden=true;$('.month-tabs').hidden=!monthlyRoles.has(asset.role);$('#currentPageLabel').textContent=`${monthlyRoles.has(asset.role)?`${fullMonths[currentMonth]} · `:''}${roleLabels[asset.role]} · ${asset.name}`;requestAnimationFrame(renderDynamicPageLayer)}
function previewAsset(id){
  const asset=journalAssets.find(item=>item.id===id);if(!asset)return
  selectedAssetId=id;if(activePreviewUrl)URL.revokeObjectURL(activePreviewUrl);activePreviewUrl=URL.createObjectURL(asset.blob);$('#journalScene').classList.remove('logical-artwork');$('#dynamicPageLayer').hidden=true;resetArtworkImageLayout($('#journalScene>img'))
  const image=$('#journalScene>img'),pdf=$('#assetPdfPreview');setStudioOverlays(true)
  if(asset.type==='application/pdf'){image.hidden=true;pdf.hidden=false;pdf.src=`${activePreviewUrl}#toolbar=0&navpanes=0&view=FitH`}else{pdf.hidden=true;pdf.removeAttribute('src');image.hidden=false;image.src=activePreviewUrl;image.style.objectFit='contain';image.style.transform='scale(1)'}
  $('#currentPageLabel').textContent=`${roleLabels[asset.role]} · ${asset.name}`;renderAssetLibrary()
}
function restoreAtelierPreview(){showDefaultAtelierScene();renderAssetLibrary()}

$('#artworkInput').addEventListener('change',async event=>{try{await receiveFiles(event.target.files)}catch(error){console.error(error);showToast('This page could not be saved')}finally{event.target.value=''}})
const dropzone=$('#uploadDropzone');['dragenter','dragover'].forEach(type=>dropzone.addEventListener(type,event=>{event.preventDefault();dropzone.classList.add('dragging')}));['dragleave','drop'].forEach(type=>dropzone.addEventListener(type,event=>{event.preventDefault();dropzone.classList.remove('dragging')}));dropzone.addEventListener('drop',event=>receiveFiles(event.dataTransfer.files).catch(error=>{console.error(error);showToast('This page could not be saved')}))
