function selectFormat(format){selectedFormat=format;$$('.format').forEach(button=>{const selected=button.dataset.format===format;button.classList.toggle('selected',selected);button.classList.toggle('goodnotes-selected',selected&&format==='goodnotes')})}
function setExportMode(mode){exportMode=mode;$$('[data-export-mode]').forEach(button=>button.classList.toggle('active',button.dataset.exportMode===mode));$('#goodnotesReady').hidden=mode!=='goodnotes';$('#exportJournal').firstChild.textContent=mode==='goodnotes'?'Export for Goodnotes ':mode==='png'?'Export Current PNG ':'Export Journal ';if(mode==='goodnotes')selectFormat('goodnotes');if(mode==='png')$('#pdfEngineStatus').textContent=`PNG export · ${fullMonths[currentMonth]} ${currentPage} page`;else markPdfEngineDirty()}

function loadPdfLibrary(){
  if(window.PDFLib)return Promise.resolve(window.PDFLib)
  return new Promise((resolve,reject)=>{const existing=$('#pdfLibLoader');if(existing){existing.addEventListener('load',()=>resolve(window.PDFLib),{once:true});existing.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.id='pdfLibLoader';script.src='https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js';script.onload=()=>resolve(window.PDFLib);script.onerror=()=>reject(new Error('PDF export library could not load'));document.head.append(script)})
}
function pageSizeForSelection(){const sizes={letter:[612,792],a4:[595.28,841.89],a5:[419.53,595.28],goodnotes:[576,768]},size=[...(sizes[selectedFormat]||sizes.letter)];return selectedOrientation==='landscape'?[size[1],size[0]]:size}
async function webpToPngBytes(blob){const bitmap=await createImageBitmap(blob),canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d').drawImage(bitmap,0,0);bitmap.close();const png=await new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error('WEBP conversion failed')),'image/png'));return new Uint8Array(await png.arrayBuffer())}
