function loadPdfJsLibrary(){if(window.pdfjsLib){window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';return Promise.resolve(window.pdfjsLib)}return new Promise((resolve,reject)=>{const existing=$('#pdfJsLoader');if(existing){existing.addEventListener('load',()=>{window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';resolve(window.pdfjsLib)},{once:true});existing.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.id='pdfJsLoader';script.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';script.onload=()=>{window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';resolve(window.pdfjsLib)};script.onerror=()=>reject(new Error('PDF artwork renderer could not load'));document.head.append(script)})}
async function artworkCanvasSource(asset,targetWidth,targetHeight){if(asset.type!=='application/pdf'){const bitmap=await createImageBitmap(asset.blob);return {source:bitmap,width:bitmap.width,height:bitmap.height,cleanup:()=>bitmap.close()}}const library=await loadPdfJsLibrary(),loading=library.getDocument({data:new Uint8Array(await asset.blob.arrayBuffer())}),pdf=await loading.promise,page=await pdf.getPage(1),base=page.getViewport({scale:1}),scale=Math.min(3,Math.max(targetWidth/base.width,targetHeight/base.height)),viewport=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;return {source:canvas,width:canvas.width,height:canvas.height,cleanup:()=>{canvas.width=0;canvas.height=0;pdf.destroy()}}}
function drawArtworkOnCanvas(context,asset,sourceInfo,width,height){const calendar=asset.role==='calendar',inset=calendar&&calendarArtworkStyle.fit==='inset'?calendarArtworkStyle.inset:0,availableWidth=width*(1-inset*2/100),availableHeight=height*(1-inset*2/100),scale=calendar&&calendarArtworkStyle.fit==='cover'?Math.max(availableWidth/sourceInfo.width,availableHeight/sourceInfo.height):Math.min(availableWidth/sourceInfo.width,availableHeight/sourceInfo.height),drawWidth=sourceInfo.width*scale,drawHeight=sourceInfo.height*scale;context.save();context.beginPath();context.rect(0,0,width,height);context.clip();context.drawImage(sourceInfo.source,(width-drawWidth)/2,(height-drawHeight)/2,drawWidth,drawHeight);context.restore()}
