const drawMonthlyCanvasLayers=drawDynamicCanvas
drawDynamicCanvas=function(context,width,height,role){if(!['front-cover','back-cover'].includes(role)){drawMonthlyCanvasLayers(context,width,height,role);return}const title=$('#journalTitle').value.trim();if(!title)return;const [,pageHeight]=pageSizeForSelection(),scaleY=height/pageHeight;let size=34*scaleY;context.save();context.textAlign='center';context.textBaseline='middle';context.fillStyle='#f3d9ad';context.shadowColor='rgba(38,4,17,.95)';context.shadowBlur=4*scaleY;context.shadowOffsetX=1.2*scaleY;context.shadowOffsetY=1.8*scaleY;do{context.font=`700 italic ${size}px Georgia, serif`;if(context.measureText(title).width<=width*.8)break;size-=scaleY}while(size>18*scaleY);context.fillText(title,width/2,height*(role==='back-cover'?.82:.5));context.restore()}
function downloadPreparedFile(file,fileName){const url=URL.createObjectURL(file),anchor=document.createElement('a');anchor.href=url;anchor.download=fileName;anchor.rel='noopener';document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function shareOrDownloadFile(file,fileName,shareData){const mobileShare=matchMedia('(pointer:coarse)').matches&&typeof navigator.share==='function'&&navigator.canShare?.({files:[file]});if(mobileShare){try{await navigator.share({files:[file],...shareData});return 'shared'}catch(error){if(error.name==='AbortError')throw error;console.warn('Mobile share unavailable; downloading instead.',error)}}downloadPreparedFile(file,fileName);return 'downloaded'}
async function deliverPngFile(blob,fileName){const file=new File([blob],fileName,{type:'image/png'});return shareOrDownloadFile(file,fileName,{title:'Share VOLUNELLE page',text:'Your finished journal page is ready.'})}
async function exportCurrentPng(){const asset=logicalAssetForCurrentPage();if(!asset){openInspectorPanel('artwork');showToast(`Add a ${roleLabels[{cover:'front-cover',divider:'divider',calendar:'calendar',entry:'entry',back:'back-cover'}[currentPage]].toLowerCase()} master before exporting PNG`);return}const button=$('#exportJournal'),original=button.innerHTML;button.disabled=true;button.innerHTML='Rendering PNG <span>◇</span>';try{const [pageWidth,pageHeight]=pageSizeForSelection(),scale=2,width=Math.round(pageWidth*scale),height=Math.round(pageHeight*scale),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.fillStyle='#fffaf5';context.fillRect(0,0,width,height);const source=await artworkCanvasSource(asset,width,height);try{drawArtworkOnCanvas(context,asset,source,width,height)}finally{source.cleanup()}drawDynamicCanvas(context,width,height,asset.role);if($('#includePageNumbers').checked){context.fillStyle='rgba(74,16,39,.72)';context.font=`${8*scale}px Arial, sans-serif`;context.textAlign='center';context.textBaseline='alphabetic';context.fillText(String(pageNumber),width/2,height-12*scale)}const blob=await new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error('PNG encoding failed')),'image/png'));const fileName=`${safeFileName($('#journalTitle').value)}-${fullMonths[currentMonth].toLowerCase()}-${currentPage}.png`,delivery=await deliverPngFile(blob,fileName);$('#pdfEngineStatus').textContent=`PNG · ${width} × ${height} · ${Math.round(blob.size/1024)} KB`;showToast(delivery==='shared'?'PNG opened in your share sheet':'Current journal page PNG downloaded')}catch(error){console.error(error);showToast(error.name==='AbortError'?'Sharing cancelled':'The PNG page could not be prepared')}finally{button.disabled=false;button.innerHTML=original}}
async function addImagePage(document,asset,imageCache,compactGoodnotes=false){let image=imageCache.get(asset.id);if(!image){if(compactGoodnotes){image=await document.embedJpg(await compactGoodnotesImageBytes(asset.blob))}else{const raw=asset.type==='image/webp'?await webpToPngBytes(asset.blob):new Uint8Array(await asset.blob.arrayBuffer());image=asset.type==='image/png'||asset.type==='image/webp'?await document.embedPng(raw):await document.embedJpg(raw)}imageCache.set(asset.id,image)}const [width,height]=pageSizeForSelection(),page=document.addPage([width,height]),calendar=asset.role==='calendar',inset=calendar&&calendarArtworkStyle.fit==='inset'?calendarArtworkStyle.inset:0,availableWidth=width*(1-inset*2/100),availableHeight=height*(1-inset*2/100),scale=calendar&&calendarArtworkStyle.fit==='cover'?Math.max(availableWidth/image.width,availableHeight/image.height):Math.min(availableWidth/image.width,availableHeight/image.height),drawWidth=image.width*scale,drawHeight=image.height*scale;page.drawImage(image,{x:(width-drawWidth)/2,y:(height-drawHeight)/2,width:drawWidth,height:drawHeight});return [page]}
async function addPdfPages(document,asset,PDFDocument,sourceCache){let source=sourceCache.get(asset.id);if(!source){source=await PDFDocument.load(new Uint8Array(await asset.blob.arrayBuffer()),{ignoreEncryption:true});sourceCache.set(asset.id,source)}const pages=await document.copyPages(source,source.getPageIndices());pages.forEach(page=>document.addPage(page));return pages}
function buildLogicalPagePlan(){const byRole=role=>journalAssets.filter(asset=>asset.role===role),plan=[],year=journalYear();byRole('front-cover').forEach(asset=>plan.push({asset,role:'front-cover',month:'',year}));byRole('additional').forEach(asset=>plan.push({asset,role:'additional',month:'',year}));fullMonths.forEach((month,monthIndex)=>{const matches=role=>byRole(role).filter(asset=>asset.month==='all'||asset.month===month);matches('divider').forEach(asset=>plan.push({asset,role:'divider',month,monthIndex,year}));matches('calendar').forEach(asset=>plan.push({asset,role:'calendar',month,monthIndex,year}));const entries=matches('entry');for(let day=1;day<=daysInMonth(monthIndex,year);day+=1)entries.forEach(asset=>plan.push({asset,role:'entry',month,monthIndex,day,year}))});byRole('back-cover').forEach(asset=>plan.push({asset,role:'back-cover',month:'',year}));return plan}
function pdfColor(hex,library){const value=String(hex).replace('#',''),number=parseInt(value.length===3?value.split('').map(character=>character+character).join(''):value,16);return library.rgb(((number>>16)&255)/255,((number>>8)&255)/255,(number&255)/255)}
async function getDynamicPdfFont(document,library,family,weight,cache){const key=`${family}-${weight}`,names={serif:{normal:library.StandardFonts.TimesRoman,bold:library.StandardFonts.TimesRomanBold},sans:{normal:library.StandardFonts.Helvetica,bold:library.StandardFonts.HelveticaBold},typewriter:{normal:library.StandardFonts.Courier,bold:library.StandardFonts.CourierBold}};if(!cache.has(key))cache.set(key,await document.embedFont(names[family]?.[weight]||names.serif.normal));return cache.get(key)}
function alignedPdfX(font,text,size,anchor,align){const width=font.widthOfTextAtSize(text,size);return align==='left'?anchor:align==='right'?anchor-width:anchor-width/2}
const drawMonthlyPdfLayers=drawDynamicPdfLayers
const drawCompletePdfLayers=async function(document,library,pageRecords){const counts=await drawMonthlyPdfLayers(document,library,pageRecords);counts.coverTitles=0;const title=$('#journalTitle').value.trim();if(!title)return counts;const font=await document.embedFont(library.StandardFonts.TimesRomanBoldItalic);for(const record of pageRecords.filter(item=>['front-cover','back-cover'].includes(item.role))){const {width,height}=record.page.getSize(),maxWidth=width*.8;let size=34;while(font.widthOfTextAtSize(title,size)>maxWidth&&size>18)size-=1;const x=(width-font.widthOfTextAtSize(title,size))/2,y=height*(record.role==='back-cover'?.18:.5)-size*.34;record.page.drawText(title,{x:x+1.2,y:y-1.2,size,font,color:library.rgb(.15,.02,.07),opacity:.92});record.page.drawText(title,{x,y,size,font,color:library.rgb(.95,.78,.52),opacity:1});counts.coverTitles+=1}return counts}
drawDynamicPdfLayers=drawCompletePdfLayers
const drawAuditedPdfLayers=drawDynamicPdfLayers
drawDynamicPdfLayers=async function(...args){const counts=await drawAuditedPdfLayers(...args);$('#pdfEngineStatus').dataset.coverTitles=String(counts.coverTitles||0);return counts}
async function drawDynamicPdfLayers(document,library,pageRecords){const fontCache=new Map(),counts={monthLabels:0,calendars:0,calendarDates:0};for(const record of pageRecords){const {page,role,month,monthIndex,year}=record;if(role==='divider'){const style=dynamicStyle.divider,font=await getDynamicPdfFont(document,library,style.font,style.weight,fontCache),{width,height}=page.getSize(),size=style.size,x=width*style.x/100,y=height*(1-style.y/100)-size*.34,textX=alignedPdfX(font,month,size,x,style.align),color=pdfColor(style.color,library);if(style.shadow)page.drawText(month,{x:textX+1.2,y:y-1.2,size,font,color:library.rgb(.12,.02,.06),opacity:.28});page.drawText(month,{x:textX,y,size,font,color,opacity:1});counts.monthLabels+=1;continue}if(role!=='calendar')continue;const style=dynamicStyle.calendar,font=await getDynamicPdfFont(document,library,style.font,'normal',fontCache),boldFont=await getDynamicPdfFont(document,library,style.font,'bold',fontCache),{width,height}=page.getSize(),color=pdfColor(style.color,library),header=`${month} ${year}`,headerSize=style.headerSize,headerAnchor=width*style.headerX/100,headerY=height*(1-style.headerY/100)-headerSize*.34;page.drawText(header,{x:alignedPdfX(boldFont,header,headerSize,headerAnchor,'center'),y:headerY,size:headerSize,font:boldFont,color,opacity:1});const gridX=width*style.gridX/100,gridTop=height*(1-style.gridY/100),gridWidth=width*style.gridWidth/100,gridHeight=height*style.gridHeight/100,gridBottom=gridTop-gridHeight,cellWidth=gridWidth/7,cellHeight=gridHeight/7;if(style.gridLines){for(let column=0;column<=7;column+=1)page.drawLine({start:{x:gridX+column*cellWidth,y:gridBottom},end:{x:gridX+column*cellWidth,y:gridTop},thickness:.55,color,opacity:.2});for(let row=0;row<=7;row+=1)page.drawLine({start:{x:gridX,y:gridBottom+row*cellHeight},end:{x:gridX+gridWidth,y:gridBottom+row*cellHeight},thickness:.55,color,opacity:.2})}const weekdaySize=Math.max(5,Math.min(8,cellHeight*.22));['SUN','MON','TUE','WED','THU','FRI','SAT'].forEach((day,column)=>{const x=gridX+column*cellWidth+(cellWidth-boldFont.widthOfTextAtSize(day,weekdaySize))/2,y=gridTop-cellHeight+cellHeight*.43;page.drawText(day,{x,y,size:weekdaySize,font:boldFont,color})});const dateSize=Math.max(6,Math.min(10,cellHeight*.25)),firstDay=new Date(year,monthIndex,1).getDay(),totalDays=daysInMonth(monthIndex,year);for(let day=1;day<=totalDays;day+=1){const index=firstDay+day-1,column=index%7,row=Math.floor(index/7)+1,label=String(day),x=gridX+column*cellWidth+(cellWidth-font.widthOfTextAtSize(label,dateSize))/2,y=gridTop-(row+1)*cellHeight+cellHeight*.58;page.drawText(label,{x,y,size:dateSize,font,color});counts.calendarDates+=1}counts.calendars+=1}return counts}
async function addMonthNavigation(document,library,pageRecords,destinations){const tabFont=await document.embedFont(library.StandardFonts.HelveticaBold);let hyperlinkCount=0;pageRecords.filter(record=>!['front-cover','back-cover'].includes(record.role)).forEach(record=>{const {width,height}=record.page.getSize(),tabWidth=Math.max(25,Math.min(34,width*.055)),gap=2,top=height-24,tabHeight=Math.min(30,(height-48-gap*11)/12);fullMonths.forEach((month,index)=>{const target=destinations.get(month),x=width-tabWidth,y=top-(index+1)*tabHeight-index*gap,active=record.month===month;record.page.drawRectangle({x,y,width:tabWidth,height:tabHeight,color:active?library.rgb(.39,.055,.17):library.rgb(.13,.025,.07),borderColor:library.rgb(.77,.55,.28),borderWidth:.55,opacity:.96});const label=months[index],size=Math.max(5,Math.min(7,tabHeight*.28)),textWidth=tabFont.widthOfTextAtSize(label,size);record.page.drawText(label,{x:x+(tabWidth-textWidth)/2,y:y+(tabHeight-size)/2+.5,size,font:tabFont,color:active?library.rgb(1,.88,.68):library.rgb(.91,.72,.46)});const annotation=document.context.obj({Type:library.PDFName.of('Annot'),Subtype:library.PDFName.of('Link'),Rect:[x,y,x+tabWidth,y+tabHeight],Border:[0,0,0],Dest:[target.page.ref,library.PDFName.of('Fit')]});record.page.node.addAnnot(document.context.register(annotation));hyperlinkCount+=1})});return hyperlinkCount}
function entryTextFieldName(record,sequence){const month=String(record.month||'journal').toLowerCase(),day=String(record.day||sequence+1).padStart(2,'0'),page=String(record.pageNumber).padStart(3,'0');return `${month}-entry-day-${day}-page-${page}-notes`}
async function addEntryTextFields(document,library,pageRecords){const entries=pageRecords.filter(record=>record.role==='entry');if(!entries.length)return {fillableFieldCount:0,fillableEntryPages:[]};const form=document.getForm(),font=await document.embedFont(library.StandardFonts.Helvetica),fieldNames=[];entries.forEach((record,index)=>{const {width,height}=record.page.getSize(),edgeInset=2,navigationReserve=Math.max(38,width*.07),field=form.createTextField(entryTextFieldName(record,index));field.enableMultiline();field.enableScrolling?.();field.addToPage(record.page,{x:edgeInset,y:edgeInset,width:width-edgeInset-navigationReserve,height:height-edgeInset*2,borderWidth:0,textColor:library.rgb(.18,.15,.16)});const widget=field.acroField.getWidgets().at(-1),appearance=widget?.getAppearanceCharacteristics();appearance?.dict.delete(library.PDFName.of('BG'));appearance?.dict.delete(library.PDFName.of('BC'));field.setFontSize(Math.max(10,Math.min(13,width*.021)));fieldNames.push(field.getName())});form.updateFieldAppearances(font);form.acroForm.dict.set(library.PDFName.of('NeedAppearances'),library.PDFBool.True);return {fillableFieldCount:fieldNames.length,fillableEntryPages:fieldNames}}
function safeFileName(value){return String(value||'volunelle-journal').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'volunelle-journal'}
async function deliverGoodnotesFile(bytes,fileName){const file=new File([bytes],fileName,{type:'application/pdf'});return shareOrDownloadFile(file,fileName,{title:'Open in Goodnotes',text:'Your VOLUNELLE journal is ready for Goodnotes.'})}

async function exportJournalForGoodnotes(){
  if(exportMode==='png'){await exportCurrentPng();return}
  if(!journalAssets.length){openInspectorPanel('artwork');showToast('Add at least one journal page before exporting');return}
  const button=$('#exportJournal'),original=button.innerHTML;button.disabled=true;button.innerHTML='Preparing pages <span>◇</span>'
  try{
    const library=await loadPdfLibrary(),document=await library.PDFDocument.create(),compactGoodnotes=exportMode==='goodnotes',plan=buildLogicalPagePlan(),pageRecords=[],imageCache=new Map(),sourceCache=new Map();document.setTitle($('#journalTitle').value||'VOLUNELLE Journal');document.setAuthor('Crown&Craft Studio');document.setCreator('VOLUNELLE Maison de Journaux by Crown&Craft Studio')
    for(let index=0;index<plan.length;index+=1){button.innerHTML=`Preparing ${index+1} of ${plan.length} <span>◇</span>`;const item=plan[index],pages=item.asset.type==='application/pdf'?await addPdfPages(document,item.asset,library.PDFDocument,sourceCache):await addImagePage(document,item.asset,imageCache,compactGoodnotes),firstPageNumber=document.getPageCount()-pages.length+1;pages.forEach((page,pageIndex)=>pageRecords.push({...item,page,pageNumber:firstPageNumber+pageIndex}))}
    const dynamicCounts=await drawDynamicPdfLayers(document,library,pageRecords)
    const formCounts=await addEntryTextFields(document,library,pageRecords)
    const destinations=new Map();fullMonths.forEach(month=>{const divider=pageRecords.find(record=>record.month===month&&record.role==='divider');if(divider)destinations.set(month,divider)})
    if($('#includeHyperlinks').checked&&destinations.size!==12)throw new Error(`MONTH_DESTINATIONS:${fullMonths.filter(month=>!destinations.has(month)).join(', ')}`)
    const hyperlinkCount=$('#includeHyperlinks').checked?await addMonthNavigation(document,library,pageRecords,destinations):0
    if($('#includePageNumbers').checked){const font=await document.embedFont(library.StandardFonts.Helvetica);document.getPages().forEach((page,index)=>{const {width}=page.getSize(),label=String(index+1);page.drawText(label,{x:width/2-font.widthOfTextAtSize(label,8)/2,y:12,size:8,font,color:library.rgb(.35,.18,.24),opacity:.72})})}
    const bytes=await document.save({useObjectStreams:compactGoodnotes}),suffix=compactGoodnotes?'goodnotes':'journal',fileName=`${safeFileName($('#journalTitle').value)}-${suffix}.pdf`,sizeLabel=bytes.length<1048576?`${Math.round(bytes.length/1024)} KB`:`${(bytes.length/1048576).toFixed(2)} MB`;window.volunelleLastExportAudit={fileName,year:journalYear(),pageCount:pageRecords.length,byteSize:bytes.length,compactGoodnotes,hyperlinkCount,...dynamicCounts,...formCounts,entryPages:Object.fromEntries(fullMonths.map(month=>[month,pageRecords.filter(record=>record.role==='entry'&&record.month===month).length])),dividerDestinations:Object.fromEntries(fullMonths.map(month=>[month,destinations.get(month)?.pageNumber||null]))};$('#pdfEngineStatus').textContent=`PDF engine · ${pageRecords.length} pages · ${formCounts.fillableFieldCount} entry fields · ${hyperlinkCount} links · ${sizeLabel}`;const delivery=await deliverGoodnotesFile(bytes,fileName)
    showToast(delivery==='shared'?'Journal opened in your share sheet':'Hyperlinked journal PDF downloaded')
  }catch(error){console.error(error);if(String(error.message).startsWith('MONTH_DESTINATIONS:')){$('#pdfEngineStatus').textContent='PDF engine · add a master month divider';showToast(`Missing divider destinations: ${error.message.split(':')[1]}`)}else showToast(error.name==='AbortError'?'Sharing cancelled':'The journal PDF could not be prepared')}
  finally{button.disabled=false;button.innerHTML=original}
}
$('#exportJournal').addEventListener('click',exportJournalForGoodnotes)
